changeSet.sql:
ALTER FUNCTION [dbo].[GenerateAssetUrl] ( @AssetID bigint ) RETURNS varchar(500) AS BEGIN declare @Url varchar(500) = ''; declare @Type varchar(50), @TypeID int, @ObjectID int = 0;
select @ObjectID = A.ObjectID, @Type = A.[Object], @TypeID = T.ObjectID from Asset A inner join AssetType T on T.ID = A.AssetTypeID where A.ID = @AssetID;
SET @Url = CASE @Type WHEN 'Artifact' THEN 'artifact/' + + CAST(@TypeID as varchar) + '/' + CAST(@ObjectID as varchar) WHEN 'ReferenceItem' THEN 'reference/' + + CAST(@TypeID as varchar) WHEN 'FusionAttribute' THEN 'fusion/fusionattribute/' + CAST(@TypeID as varchar) + '/' + CAST(@ObjectID as varchar) WHEN 'Fusion' THEN 'fusion/' + CAST(@TypeID as varchar) + '/' + + CAST(@ObjectID as varchar) WHEN 'Group' THEN 'group/' + CAST(@ObjectID as varchar) WHEN 'Policy' THEN 'policy/' + CAST(@TypeID as varchar(15)) + '/id/' + CAST(@ObjectID as varchar) WHEN 'Resource' THEN 'resource/' + CAST(@ObjectID as varchar) WHEN 'Rule' THEN 'quality/rule/' + CAST(@TypeID as varchar) + '/' + CAST(@ObjectID as varchar) WHEN 'Taxonomy' THEN 'model/' + CAST(@TypeID as varchar) + '/id/' + CAST(@ObjectID as varchar) END
RETURN @Url END

